/**
 * VNA Route Manual v4.0 - Pure Node.js Bundle Generator
 * Bundles src/ ES modules into assets/vna-rm-bundle.js for zero-setup standalone file:// execution.
 * No npm dependencies required.
 *
 * Usage: node tools/build-bundle.mjs
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const APP_DIR = path.resolve(__dirname, '..', 'vna-rm-app');
const SRC_DIR = path.join(APP_DIR, 'src');
const OUTPUT_BUNDLE = path.join(APP_DIR, 'assets', 'vna-rm-bundle.js');

// Dependency-ordered list of source modules
const MODULE_ORDER = [
  'parsers/ooxmlUtils.js',
  'parsers/chapter3Parser.js',
  'parsers/chapter4Parser.js',
  'db/idbStore.js',
  'db/seedData.js',
  'utils/userPrefs.js',
  'utils/router.js',
  'utils/airportLinker.js',
  'components/ImageLightboxModal.js',
  'components/AirportHoverCard.js',
  'components/Chapter4TableView.js',
  'components/AirportSlideDrawer.js',
  'components/Chapter3TableView.js',
  'components/SidebarNav.js',
  'main.js'
];

function transformModule(code, relPath) {
  let transformed = code;

  // 1. Remove import statements (single-line and multi-line)
  transformed = transformed.replace(/^import\s+[\s\S]*?from\s+['"][^'"]+['"];?/gm, '');
  transformed = transformed.replace(/^import\s+['"][^'"]+['"];?/gm, '');

  // 2. Remove standalone export statements: export { ... };
  transformed = transformed.replace(/^export\s*\{[\s\S]*?\};?/gm, '');
  transformed = transformed.replace(/^export\s+default\s+[\w$]+;?/gm, '');

  // 3. Convert export declarations: export class Foo -> class Foo
  transformed = transformed.replace(/^export\s+default\s+class\s+/gm, 'class ');
  transformed = transformed.replace(/^export\s+default\s+async\s+function\s+/gm, 'async function ');
  transformed = transformed.replace(/^export\s+default\s+function\s+/gm, 'function ');
  transformed = transformed.replace(/^export\s+class\s+/gm, 'class ');
  transformed = transformed.replace(/^export\s+async\s+function\s+/gm, 'async function ');
  transformed = transformed.replace(/^export\s+function\s+/gm, 'function ');
  transformed = transformed.replace(/^export\s+const\s+/gm, 'const ');
  transformed = transformed.replace(/^export\s+let\s+/gm, 'let ');
  transformed = transformed.replace(/^export\s+var\s+/gm, 'var ');

  return `\n// --- MODULE: ${relPath} ---\n${transformed.trim()}\n`;
}

function buildBundle() {
  console.log('====================================================');
  console.log(' VNA Route Manual v4.0 - Standalone Bundle Builder');
  console.log('====================================================');
  console.log(`Source dir: ${SRC_DIR}`);
  console.log(`Target:     ${OUTPUT_BUNDLE}\n`);

  let bundleBody = '';

  for (const relPath of MODULE_ORDER) {
    const fullPath = path.join(SRC_DIR, relPath);
    if (!fs.existsSync(fullPath)) {
      throw new Error(`Module file not found: ${fullPath}`);
    }
    const code = fs.readFileSync(fullPath, 'utf8');
    console.log(` [+] Bundling ${relPath} (${code.length} bytes)`);
    bundleBody += transformModule(code, relPath);
  }

  const banner = `/**
 * VNA Route Manual v4.0 - Unified Application Standalone Bundle
 * Generated by tools/build-bundle.mjs on ${new Date().toISOString()}
 * Synchronized with src/ ES modules. DO NOT EDIT DIRECTLY.
 */
(function() {
  'use strict';

  // Prevent double initialization if already booted
  if (window.vnaApp && window.vnaApp.routes && window.vnaApp.routes.length > 0) {
    return;
  }
`;

  const footer = `\n})();\n`;

  const finalOutput = banner + bundleBody + footer;

  // Verify zero lingering export keywords
  const exportMatches = [...finalOutput.matchAll(/^\s*export\b/gm)];
  if (exportMatches.length > 0) {
    throw new Error(`Build failed: ${exportMatches.length} lingering 'export' statements found in output bundle!`);
  }

  fs.writeFileSync(OUTPUT_BUNDLE, finalOutput, 'utf8');
  console.log(`\n[SUCCESS] Standalone bundle built successfully: ${OUTPUT_BUNDLE} (${finalOutput.length} bytes)`);
}

buildBundle();
